script:
for item in doc.items:
    if item.posa_offer_applied == 0 and item.rate != item.price_list_rate:
        frappe.throw(f'Không được sửa rate tay cho item {item.item_code}. Rate phải bằng price_list_rate trước khi áp Offer.')
    elif item.posa_offer_applied == 1 and item.rate > item.price_list_rate:
        frappe.throw(f'Không được tăng rate sau khi áp Offer cho item {item.item_code}.')
